import sys; sys.path.insert(0, '/workspace/derm-teach/website/tools/v4/authoring'); from enr import *

E('lyme-disease',
  kf=["**Lyme disease** is infection with *Borrelia burgdorferi* sensu lato from an infected **Ixodes tick** bite.",
      "**Erythema migrans**: an expanding red patch (often over 5 cm) appearing 1–4 weeks after the bite: diagnose clinically, no tests needed (NICE NG95).",
      "Doxycycline 100 mg twice daily or 200 mg once daily for 21 days; amoxicillin or azithromycin as alternatives.",
      "Remove ticks with fine-tipped tweezers or a tick tool; no prophylaxis or serology after an asymptomatic bite.",
      "Later disease: facial palsy, meningitis, carditis, arthritis, acrodermatitis chronica atrophicans: specialist."],
  epi=[{"t": "**Who**", "sub": ["UK: a few thousand cases a year; New Forest, Exmoor, South Downs, Lake District, Scottish Highlands.", "Peak May–September; walkers, gardeners, outdoor workers."]}],
  aet=["Ixodes ricinus ticks; transmission usually needs prolonged attachment (over 24 hours)."],
  myths=["**\"No bull's-eye, no Lyme\"**: most EM is uniformly red, not target-like.", "**\"A negative blood test excludes it\"**: serology is often negative in early EM."],
  patho_lead="Borrelia spreads **outwards in the skin** from the bite, then through the blood.",
  mech=[("Tick bite", "An infected tick feeds for over a day; spirochaetes migrate from tick gut to saliva."),
        ("Local spread", "Borrelia spreads centrifugally in the dermis, causing the expanding erythema migrans.", "v3-erythema-migrans-expanding.jpg", "Erythema migrans expanding outwards from the bite site."),
        ("Dissemination", "Spirochaetes spread to the nervous system, heart, joints and other skin sites."),
        ("Late disease", "Persistent infection causes arthritis or acrodermatitis chronica atrophicans."),
        ("Prevention", "Prompt correct tick removal reduces transmission.", "v3-tick-removal.jpg", "Grasp close to the skin and pull steadily up.")],
  histo=["Not needed for EM. Serology (ELISA then immunoblot) for suspected disseminated disease."],
  special=[{"t": "**Pregnancy and children**", "sub": ["Amoxicillin in pregnancy; children under 12 per NG95 weight-based doses or specialist advice."]}],
  comp=["Neuroborreliosis, carditis (heart block), arthritis, ACA.", "Jarisch–Herxheimer reaction on starting treatment."],
  prog=["EM treated promptly has an excellent outlook; some have lingering fatigue."],
  see_also=["annular-rashes", "papular-urticaria-bites", "cellulitis-erysipelas", "returning-traveller-skin"])

E('papular-urticaria-bites',
  kf=["**Papular urticaria** is a persistent itchy hypersensitivity reaction to insect bites (fleas, bed bugs, mites, mosquitoes).",
      "Grouped or linear ('breakfast, lunch and dinner') papules, sometimes with central punctum or blisters, on exposed skin or ankles.",
      "Commonest in children aged 2–10; other household members may be unaffected.",
      "Eradicate the source (treat **all pets**, professional pest control for bed bugs); antihistamine and mild–moderate topical steroid.",
      "Most bites do not need antibiotics; treat only clear secondary infection."],
  epi=[{"t": "**Who**", "sub": ["Children, newcomers to a household, travellers; tolerance develops with ongoing exposure."]}],
  aet=["Type I and IV hypersensitivity to insect saliva antigens."],
  myths=["**\"Only one child is affected, so it can't be bites\"**: sensitivity varies between people."],
  patho_lead="The rash is an **allergic reaction to insect saliva**, not the bite itself.",
  mech=[("Bite", "The insect injects saliva containing anticoagulant and enzyme proteins."),
        ("Immediate reaction", "IgE on mast cells triggers a wheal within minutes."),
        ("Delayed reaction", "T cells respond over 24–48 hours, producing a firm itchy papule that lasts days to weeks.", "v3-bites-ankle-clusters.jpg", "Clusters of bites on the ankle."),
        ("Desensitisation", "With repeated exposure, reactions fade (tolerance).")],
  histo=["Wedge-shaped perivascular infiltrate with eosinophils; rarely needed."],
  special=[{"t": "**Bed bugs**", "sub": ["Linear bites on the face, neck and arms; blood spots on sheets; professional eradication needed."]}],
  comp=["Impetigo, scarring, post-inflammatory pigmentation, sleep disturbance."],
  prog=["Settles when the source is removed; children grow out of it."],
  see_also=["scabies", "urticaria-angioedema", "impetigo", "lyme-disease", "cutaneous-larva-migrans"])

E('keratolysis-exfoliativa',
  kf=["**Keratolysis exfoliativa** is recurrent, painless superficial peeling of the palms (and soles), worse in warm weather.",
      "Air-filled blisters burst into expanding **collarettes** of scale with no inflammation.",
      "Benign, not contagious, not an allergy; often confused with hand eczema or tinea.",
      "Irritant avoidance, emollients and keratolytic creams (urea, lactic acid); topical steroids do not help.",
      "Scrape for fungus if one-sided or with a raised edge."],
  epi=[{"t": "**Who**", "sub": ["Young adults; often associated with sweaty hands; summer flares."]}],
  aet=["Unknown; possibly a variant of mild pompholyx or an inherited keratin defect; friction, water and detergents aggravate."],
  myths=["**\"It's eczema, use steroid\"**: there is no inflammation, so steroids are wasted and thin the skin."],
  patho_lead="The outer **stratum corneum splits**, forming air-filled blisters that peel.",
  mech=[("Corneal splitting", "Cohesion within the stratum corneum fails, creating an air space.", "v3-ke-stratum-split.jpg", "A split within the stratum corneum forms an air-filled blister."),
        ("Expanding collarettes", "The roof peels outwards, leaving rings of scale over normal skin.", "v3-ke-collarette-stages.jpg", "Air blister → collarette → peeling."),
        ("Healing", "New stratum corneum forms beneath within 1–3 weeks.")],
  histo=["Rarely needed: splitting within the upper stratum corneum without inflammation."],
  comp=["Tender fissures and secondary irritant dermatitis."],
  prog=["Recurrent; improves with age."],
  see_also=["hand-eczema", "tinea", "palmoplantar-pustulosis", "hyperhidrosis"])

E('palmoplantar-pustulosis',
  kf=["**Palmoplantar pustulosis (PPP)** is a chronic, relapsing eruption of sterile yellow pustules on the palms and soles that turn brown and scale.",
      "Strongly linked to **smoking** (most patients smoke or have smoked); mainly women aged 40–60.",
      "Distinct from palmoplantar psoriasis, though some have psoriasis elsewhere.",
      "Stop smoking; very potent topical steroid (clobetasol) ± occlusion; refer for hand–foot PUVA, acitretin or other systemics.",
      "Screen for thyroid disease and coeliac disease if symptomatic; SAPHO (bone pain) is a rare association."],
  epi=[{"t": "**Who**", "sub": ["Women 3–4× more often; peak 40–60; uncommon (about 1 in 1,000–10,000)."]}],
  aet=["Smoking (nicotine receptors on eccrine sweat ducts), genetics (IL-36 pathway), focal infection; thyroid autoimmunity."],
  myths=["**\"The pustules are infected\"**: they are sterile; antibiotics do not help."],
  patho_lead="PPP begins in the **eccrine sweat duct**, where neutrophils gather into sterile pustules.",
  mech=[("Duct inflammation", "Nicotine and other triggers activate the acrosyringium (top of the sweat duct)."),
        ("IL-36 / IL-17 axis", "Innate cytokines recruit neutrophils."),
        ("Pustule evolution", "Vesicle → yellow pustule → brown macule → scale.", "v3-ppp-pustule-evolution.jpg", "PPP lesions evolve from vesicle to pustule to brown scale."),
        ("Distribution", "Central palms, thenar and hypothenar eminences, heels and insteps.", "v3-ppp-hand-foot-map.jpg", "Typical PPP sites.")],
  histo=["Intraepidermal unilocular pustule filled with neutrophils, near the eccrine duct."],
  special=[{"t": "**Drug-induced**", "sub": ["TNF inhibitors can cause paradoxical PPP."]}],
  comp=["Pain, fissures, difficulty walking and working; impaired quality of life."],
  prog=["Chronic, with remission in some after stopping smoking."],
  see_also=["psoriasis", "hand-eczema", "tinea", "keratolysis-exfoliativa", "biologics-systemics"])

E('erythema-multiforme',
  kf=["**Erythema multiforme (EM)** is an acute immune reaction with **target lesions** (three zones), mostly triggered by **herpes simplex**.",
      "Acral (hands, feet, elbows, knees), symmetrical, appears over 24–72 hours; EM major also involves mucosa.",
      "Not part of the SJS/TEN spectrum: SJS has atypical flat targets, widespread blistering and is usually drug-induced.",
      "Supportive care; treat HSV; recurrent HSV-associated EM may need antiviral prophylaxis (specialist).",
      "Urgent same-day care if mucosal involvement impairs eating, eyes are affected or skin is blistering."],
  epi=[{"t": "**Who**", "sub": ["Young adults 20–40; recurs in some with recurrent HSV."]}],
  aet=["HSV (most), *Mycoplasma pneumoniae* (especially children), other infections; drugs less often."],
  myths=["**\"EM is mild SJS\"**: they are different diseases with different causes and outlooks."],
  patho_lead="EM is a **T-cell reaction to viral DNA** deposited in the skin.",
  mech=[("HSV DNA in skin", "Fragments of HSV DNA are carried to distant skin by blood cells."),
        ("T-cell response", "HSV-specific T cells release interferon-γ, damaging keratinocytes."),
        ("Target zones", "Dusky or blistered centre (necrosis), pale oedematous ring, red outer ring.", "v3-em-target-zones.jpg", "The three zones of a typical target lesion."),
        ("Acral distribution", "Lesions favour the hands, feet and extensor limbs.", "v3-em-acral-hands.jpg", "Acral target lesions on the hands.")],
  histo=["Interface dermatitis with necrotic keratinocytes; HSV PCR from a cold sore may help."],
  special=[{"t": "**Children**", "sub": ["Mycoplasma-induced rash and mucositis (MIRM) causes severe mucositis with few skin lesions."]}],
  comp=["Eye scarring in EM major; dehydration from painful mouth."],
  prog=["Resolves in 2–4 weeks without scarring; recurrences common with HSV."],
  see_also=["herpes-simplex-labialis", "drug-induced-blistering", "urticaria-angioedema", "fixed-drug-eruption", "annular-rashes"])

E('erythema-nodosum',
  kf=["**Erythema nodosum (EN)** is a **septal panniculitis**: tender red nodules on the shins that bruise as they heal.",
      "Often with fever, malaise and arthralgia; lasts 3–6 weeks; does not ulcerate or scar.",
      "Causes: streptococcal throat, sarcoidosis, IBD, pregnancy, drugs (combined pill), TB; about half idiopathic.",
      "Tests: FBC, CRP, ASO titre, chest X-ray (bilateral hilar lymphadenopathy), throat swab; others guided by history.",
      "Treat the cause; rest, elevation, compression and NSAIDs."],
  epi=[{"t": "**Who**", "sub": ["Women 3–6× more often; age 20–45; commonest panniculitis."]}],
  aet=["Delayed hypersensitivity to infection (streptococcus, TB, Yersinia), sarcoidosis, IBD, pregnancy, drugs, malignancy (lymphoma)."],
  myths=["**\"It's a bruise or cellulitis\"**: bilateral tender nodules plus systemic symptoms point to EN."],
  patho_lead="EN is an **immune reaction in the fibrous septa** between fat lobules.",
  mech=[("Antigen exposure", "An infection, drug or systemic disease provides the antigen."),
        ("Immune complex / T-cell reaction", "Immune reactions target the septal blood vessels of the subcutaneous fat."),
        ("Septal panniculitis", "Inflammatory cells thicken the septa while lobules are spared.", "v4-en-septal-panniculitis.jpg", "Erythema nodosum: inflammation thickens the fibrous septa between fat lobules (septal panniculitis), causing a tender red nodule."),
        ("Resolution", "Haemoglobin breakdown changes colour from red to purple to yellow-green, like a bruise.")],
  histo=["Septal panniculitis without vasculitis; Miescher radial granulomas. Biopsy only if atypical (deep incisional)."],
  special=[{"t": "**Löfgren syndrome**", "sub": ["EN + bilateral hilar lymphadenopathy + fever + arthritis: acute sarcoidosis with a good prognosis."]}],
  comp=["Pain, arthralgia; complications depend on the cause."],
  prog=["Resolves in 3–6 weeks; recurrence possible if the cause persists."],
  see_also=["sarcoidosis", "cellulitis-erysipelas", "cutaneous-vasculitis-approach", "cutaneous-tuberculosis", "pyoderma-gangrenosum"])

E('fixed-drug-eruption',
  kf=["**Fixed drug eruption (FDE)** recurs at the **same site** each time the culprit drug is taken.",
      "Round dusky red-purple patch, sometimes blistering, within hours; lips, genitals, hands, face; leaves grey-brown pigmentation.",
      "Culprits: NSAIDs, paracetamol, co-trimoxazole, tetracyclines, laxatives (phenolphthalein historically).",
      "Stop and avoid the drug; record the allergy; potent topical steroid for a few days.",
      "Generalised bullous FDE can mimic SJS/TEN: urgent assessment."],
  epi=[{"t": "**Who**", "sub": ["Any age; often over-the-counter painkillers; recurrent episodes before diagnosis."]}],
  aet=["Intermittent use of a drug, often OTC."],
  myths=["**\"It's an infection like herpes\"**: recurrence at the same site after a drug points to FDE (genital FDE is often mistaken for HSV)."],
  patho_lead="FDE is caused by **memory T cells that stay in the skin** at the original site.",
  mech=[("First reaction", "The drug triggers CD8+ T cells that attack keratinocytes at one site."),
        ("Resident memory", "Some CD8+ T cells remain in the epidermis of that patch long-term.", "v4-fde-resident-t.jpg", "Fixed drug eruption: memory T cells resting at the site (left) are reactivated by the drug, causing interface damage, a blister and a dusky patch (right)."),
        ("Re-exposure", "Each dose reactivates them within hours, causing a dusky patch, sometimes with blistering."),
        ("Pigment", "Damaged basal cells drop melanin into the dermis, leaving persistent brown-grey pigment.")],
  histo=["Interface dermatitis with necrotic keratinocytes and pigment incontinence; eosinophils."],
  special=[{"t": "**Skin of colour**", "sub": ["Pigmentation is marked and long-lasting."]}],
  comp=["Persistent pigmentation; generalised bullous FDE (rare, serious)."],
  prog=["Does not recur if the drug is avoided; pigment fades slowly."],
  see_also=["drug-eruption-approach", "erythema-multiforme", "drug-induced-blistering", "herpes-simplex-labialis", "drug-induced-pigmentation"])

E('morbilliform-drug-eruption',
  kf=["**Morbilliform (maculopapular) drug eruption** is the commonest drug rash: measles-like pink macules and papules starting on the trunk.",
      "Begins 4–14 days after starting a drug (sooner on re-exposure); itchy, symmetrical; mucosa spared.",
      "Common culprits: aminopenicillins, cephalosporins, sulfonamides, anticonvulsants, allopurinol.",
      "Stop the drug; emollient plus moderate or potent topical steroid for 5–7 days; antihistamine for itch.",
      "Red flags for **DRESS** (fever, facial oedema, lymph nodes, eosinophilia, abnormal liver tests) or **SJS/TEN** (pain, blisters, mucosa): urgent referral."],
  epi=[{"t": "**Who**", "sub": ["About 1–3% of hospital inpatients; amoxicillin rash in EBV infection is classic."]}],
  aet=["T-cell mediated (type IV) hypersensitivity; viral infection (EBV, HIV) increases risk."],
  myths=["**\"An amoxicillin rash in glandular fever means lifelong penicillin allergy\"**: often it does not; refer for allergy testing if unsure."],
  patho_lead="Drug-specific **T cells** recognise the drug bound to proteins in the skin.",
  mech=[("Sensitisation", "Over 1–2 weeks, the drug (or a drug–protein complex) activates T cells."),
        ("Skin infiltration", "Activated T cells home to the dermis and release cytokines."),
        ("Rash", "Dermal vessel dilation and mild interface damage cause pink macules and papules."),
        ("Resolution", "Clears 1–2 weeks after stopping, often with fine peeling.")],
  histo=["Superficial perivascular lymphocytes with eosinophils, mild interface change."],
  special=[{"t": "**Viral exanthem**", "sub": ["Similar appearance; fever, contacts and timing help distinguish."]}],
  comp=["Progression to DRESS or SJS/TEN (rare); misdiagnosis leading to unnecessary allergy labels."],
  prog=["Resolves in 1–2 weeks after stopping the drug."],
  see_also=["drug-eruption-approach", "dress-agep", "drug-induced-blistering", "urticaria-angioedema", "scarlet-fever"])

E('bullous-pemphigoid',
  kf=["**Bullous pemphigoid (BP)** is the commonest autoimmune blistering disease: tense blisters in older people.",
      "Often starts with weeks to months of **itch** and urticarial plaques before blisters (prodrome).",
      "Autoantibodies against **BP180 and BP230** at the basement membrane; confirm with biopsy and immunofluorescence.",
      "Localised: clobetasol; mild–moderate: **doxycycline 200 mg once daily** (BLISTER trial: safer than prednisolone).",
      "Check drugs: **DPP-4 inhibitors (gliptins)**, diuretics, checkpoint inhibitors; associated with neurological disease (stroke, dementia, Parkinson's)."],
  epi=[{"t": "**Who**", "sub": ["Mostly over 70; incidence rising with age and drugs; UK about 4,000 new cases a year."]}],
  aet=["Autoimmunity to hemidesmosome proteins; drug triggers (gliptins, loop diuretics, spironolactone, PD-1 inhibitors)."],
  myths=["**\"Blisters in older people are just friction\"**: itchy urticarial plaques with tense blisters need biopsy."],
  patho_lead="Antibodies attack the **anchors holding the epidermis to the dermis**, so it separates as a tense blister.",
  mech=[("Autoantibodies", "IgG autoantibodies bind BP180 (collagen XVII) and BP230 in hemidesmosomes."),
        ("Complement and eosinophils", "Complement activation recruits eosinophils and neutrophils that release proteases."),
        ("Subepidermal split", "The whole epidermis lifts off: a **tense, roofed blister** (unlike flaccid pemphigus).", "v3-bp-vs-pv-split.jpg", "BP splits below the epidermis (tense blister); pemphigus splits within it (flaccid)."),
        ("Distribution", "Flexures, limbs and trunk; mucosa involved in a minority.", "v3-bp-body-map.jpg", "Typical BP distribution.")],
  histo=["Subepidermal blister with eosinophils; direct IF: linear IgG and C3 along the basement membrane; serum BP180/BP230 ELISA."],
  special=[{"t": "**Frail older people**", "sub": ["Whole-body clobetasol is effective but impractical without carers; doxycycline is often preferred."]}],
  comp=["Infection, sepsis, side effects of steroids; mortality about 20–40% in the first year in frail patients."],
  prog=["Usually remits over 1–5 years with treatment; relapses common."],
  see_also=["blistering-approach", "pemphigus", "dermatitis-herpetiformis", "drug-induced-blistering", "itch-xerosis-older-adults"])
